    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    marks=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (0,2)]
    # Side markers extend the solid rectangle away from the marked side, only on that row.
    for r,c in marks:
        if r0<=r<=r1 and c<c0:
            for j in range(c1+1,W):
                g[r][j]=2
        elif r0<=r<=r1 and c>c1:
            for j in range(c0):
